@layer hj.components {
  /* Rows and popups are Menu's (hj-menu-*). This file styles the bar and its triggers. */
  .hj-menubar {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 3px;
    border-radius: var(--hj-radius-sm);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    font-family: var(--hj-font-sans);
  }
  .hj-menubar[data-orientation='vertical'] {
    flex-direction: column;
    align-items: stretch;
  }
  .hj-menubar-trigger {
    position: relative;
    height: var(--hj-menubar-trigger-height, 32px);
    padding: 0 12px;
    border: 0;
    border-radius: var(--hj-radius-xs);
    background: transparent;
    color: var(--hj-fg-dim);
    font: 500 13.5px / 1 var(--hj-font-sans);
    cursor: default;
    user-select: none;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-menubar-trigger:hover:not([data-disabled]),
  .hj-menubar-trigger[data-popup-open] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg);
  }
  .hj-menubar-trigger[data-disabled] {
    opacity: 0.4;
  }
  .hj-menubar-trigger:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: -2px;
  }
}

'use client';
import { Menu as BaseMenu } from '@base-ui/react/menu';
import { Menubar as Base } from '@base-ui/react/menubar';
import type * as React from 'react';

import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';

/*
 * A row of menus (File · Edit · View) that behave as one: hover moves between open menus, ←/→
 * move between triggers. Each menu's popup and rows are Menu's own parts, re-exported here.
 */
export {
  Arrow,
  Backdrop,
  CheckboxItem,
  CheckboxItemIndicator,
  Content,
  Group,
  GroupLabel,
  Item,
  LinkItem,
  Popup,
  Portal,
  Positioner,
  RadioGroup,
  RadioItem,
  RadioItemIndicator,
  Separator,
  Shortcut,
  SubmenuRoot,
  SubmenuTrigger,
} from '../menu/menu.tsx';

/** The bar. Renders a `<div role="menubar">`. */
export const Root: HanjiPart<typeof Base> = part(Base, 'Menubar.Root', 'hj-menubar');
/** One menu in the bar (Base UI Menu.Root). */
export const Menu: typeof BaseMenu.Root = BaseMenu.Root;
/** The bar's quiet text trigger. */
export const Trigger: HanjiPart<typeof BaseMenu.Trigger> = part(
  BaseMenu.Trigger,
  'Menubar.Trigger',
  'hj-menubar-trigger',
);

/** Props of the bar itself. */
export type RootProps = React.ComponentProps<typeof Base>;
